def min_coins_needed(costs):
    max_cost = max(costs)
    dp = [float('inf')] * (max_cost + 1)
    dp[0] = 0

    for cost in costs:
        for j in range(max_cost, cost - 1, -1):
            dp[j] = min(dp[j], dp[j - cost] + 1)

    return max(dp)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        costs = list(map(int, data[index:index + n]))
        index += n
        results.append(min_coins_needed(costs))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
